package bo.com.ganadero.seguridad.application;
import bo.com.ganadero.seguridad.domain.*;import bo.com.ganadero.shared.security.*;import org.springframework.context.ApplicationEventPublisher;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.Instant;import java.util.UUID;
@Service public class ActualizarRolUseCase{private final RolRepository repository;private final UserContext context;private final ApplicationEventPublisher events;public ActualizarRolUseCase(RolRepository repository,UserContext context,ApplicationEventPublisher events){this.repository=repository;this.context=context;this.events=events;}
 @Transactional public Rol execute(UUID id,String nombre,String descripcion,Boolean activo,long version){CurrentUser actor=context.requirePermission("ROL_EDITAR");Rol role=repository.update(id,actor.empresaId(),nombre,descripcion,activo,version,actor.userId());events.publishEvent(new SeguridadAuditEvent(actor.empresaId(),actor.userId(),"ACTUALIZAR","ROL",id,Instant.now()));return role;}}
